#!/usr/bin/env node
/**
 * Fix Missing Customer IDs and Zeu IDs
 * 
 * Customer IDs:
 * - Created when user registers via /api/user/signup
 * - Auto-increment primary key in users table
 * - If missing, user registration failed or data corruption
 * 
 * Zeu IDs:
 * - Format: ZEU-{id} where id is the user's auto-increment ID
 * - Added in migration 006_add_zeu_id_to_users.sql
 * - Format example: ZEU-000123
 * - Generated by: CONCAT('ZEU-', LPAD(id, 6, '0'))
 * 
 * This script:
 * 1. Finds users with missing customer IDs (shouldn't happen with auto-increment)
 * 2. Finds users with missing Zeu IDs and populates them
 * 3. Reports any data integrity issues
 */

import dotenv from "dotenv";
import path from "path";
import mysql from "mysql2/promise";

// Load environment
dotenv.config({ path: path.resolve(process.cwd(), ".env") });

const pool = mysql.createPool({
  host: process.env.DB_HOST,
  port: parseInt(process.env.DB_PORT) || 4000,
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  database: process.env.DB_NAME,
  ssl: process.env.DB_SSL === "true" ? { rejectUnauthorized: false } : undefined,
  waitForConnections: true,
  connectionLimit: 5,
  queueLimit: 0,
  charset: "utf8mb4",
});

async function fixMissingIds() {
  console.log("🔍 Checking for missing Customer IDs and Zeu IDs...\n");

  try {
    // 1. Check for users with NULL or empty IDs (shouldn't happen with auto-increment)
    console.log("1. Checking for users with missing/invalid primary IDs...");
    const [nullIdUsers] = await pool.query(`
      SELECT id, name, email, phone, zeu_id, created_at
      FROM users
      WHERE id IS NULL OR id = 0 OR id = ''
    `);

    if (nullIdUsers.length > 0) {
      console.log(`   ⚠️ Found ${nullIdUsers.length} users with missing/invalid IDs:`);
      nullIdUsers.forEach(u => console.log(`      - Email: ${u.email}, Name: ${u.name}, ID: ${u.id}`));
      console.log("   🔧 These require manual investigation - auto-increment should prevent this");
    } else {
      console.log("   ✅ All users have valid primary IDs");
    }

    // 2. Check for users with missing Zeu IDs
    console.log("\n2. Checking for users with missing Zeu IDs...");
    const [missingZeuUsers] = await pool.query(`
      SELECT id, name, email, phone, zeu_id, created_at
      FROM users
      WHERE zeu_id IS NULL OR zeu_id = '' OR zeu_id NOT LIKE 'ZEU-%'
    `);

    if (missingZeuUsers.length > 0) {
      console.log(`   ⚠️ Found ${missingZeuUsers.length} users with missing/invalid Zeu IDs:`);
      missingZeuUsers.forEach(u => console.log(`      - ID: ${u.id}, Email: ${u.email}, Name: ${u.name}, Current Zeu: "${u.zeu_id}"`));

      // Fix: Generate Zeu IDs for missing ones
      console.log("\n   🔧 Generating Zeu IDs for missing users...");
      let fixed = 0;
      for (const user of missingZeuUsers) {
        const newZeuId = `ZEU-${String(user.id).padStart(6, '0')}`;
        try {
          await pool.execute(
            "UPDATE users SET zeu_id = ? WHERE id = ?",
            [newZeuId, user.id]
          );
          console.log(`   ✅ Updated user ${user.id} (${user.email}) -> ${newZeuId}`);
          fixed++;
        } catch (err) {
          console.error(`   ❌ Failed to update user ${user.id}:`, err.message);
        }
      }
      console.log(`\n   ✅ Fixed ${fixed} out of ${missingZeuUsers.length} users`);
    } else {
      console.log("   ✅ All users have valid Zeu IDs (format: ZEU-XXXXXX)");
    }

    // 3. Check for duplicate Zeu IDs
    console.log("\n3. Checking for duplicate Zeu IDs...");
    const [duplicates] = await pool.query(`
      SELECT zeu_id, COUNT(*) as count
      FROM users
      WHERE zeu_id IS NOT NULL AND zeu_id != ''
      GROUP BY zeu_id
      HAVING COUNT(*) > 1
    `);

    if (duplicates.length > 0) {
      console.log(`   ⚠️ Found ${duplicates.length} duplicate Zeu IDs:`);
      duplicates.forEach(d => console.log(`      - ${d.zeu_id}: ${d.count} occurrences`));
      
      // Fix duplicates by reassigning
      console.log("\n   🔧 Fixing duplicate Zeu IDs...");
      for (const dup of duplicates) {
        const [users] = await pool.query(
          "SELECT id FROM users WHERE zeu_id = ? ORDER BY id",
          [dup.zeu_id]
        );
        // Keep first, reassign rest
        for (let i = 1; i < users.length; i++) {
          const newZeuId = `ZEU-${String(users[i].id).padStart(6, '0')}`;
          await pool.execute("UPDATE users SET zeu_id = ? WHERE id = ?", [newZeuId, users[i].id]);
          console.log(`   ✅ Reassigned user ${users[i].id} -> ${newZeuId}`);
        }
      }
    } else {
      console.log("   ✅ No duplicate Zeu IDs found");
    }

    // 4. Check for users without IDs in orders table (orphaned orders)
    console.log("\n4. Checking for orders with missing user references...");
    const [orphanOrders] = await pool.query(`
      SELECT o.id, o.user_id, o.shopkeeper_id, o.status, o.created_at
      FROM orders o
      LEFT JOIN users u ON o.user_id = u.id
      WHERE u.id IS NULL
    `);

    if (orphanOrders.length > 0) {
      console.log(`   ⚠️ Found ${orphanOrders.length} orders with missing user references:`);
      orphanOrders.forEach(o => console.log(`      - Order ID: ${o.id}, User ID: ${o.user_id}, Status: ${o.status}`));
      console.log("   🔧 These orders reference deleted/non-existent users");
    } else {
      console.log("   ✅ All orders have valid user references");
    }

    // 5. Summary
    console.log("\n" + "=".repeat(50));
    console.log("📊 SUMMARY");
    console.log("=".repeat(50));
    
    const [totalUsers] = await pool.query("SELECT COUNT(*) as count FROM users");
    const [withZeu] = await pool.query("SELECT COUNT(*) as count FROM users WHERE zeu_id LIKE 'ZEU-%'");
    const [totalOrders] = await pool.query("SELECT COUNT(*) as count FROM orders");
    
    console.log(`   Total Users: ${totalUsers[0].count}`);
    console.log(`   Users with Zeu ID: ${withZeu[0].count}`);
    console.log(`   Total Orders: ${totalOrders[0].count}`);
    console.log("\n✅ ID integrity check complete!");

  } catch (err) {
    console.error("❌ Error during ID check:", err);
    process.exit(1);
  } finally {
    await pool.end();
  }
}

// Run the script
fixMissingIds().then(() => {
  console.log("\n🏁 Script completed");
  process.exit(0);
}).catch(err => {
  console.error("❌ Fatal error:", err);
  process.exit(1);
});